628	func (o *redhatBase) parseSourceRPM(filename, binaryName, binaryEpoch string) *models.SrcPackage {
629		if filename == "(none)" {
630			return nil
631		}
632	
633		name, version, release, err := splitFileName(filename)
634		if err != nil {
635			o.warns = append(o.warns, xerrors.Errorf("Failed to parse source rpm file %q: %w", filename, err))
636			return nil
637		}
638		if !strings.Contains(version, ":") {
639			version = rpmVersionWithEpoch(binaryEpoch, version)
640		}
641		return &models.SrcPackage{
642			Name:        name,
643			Version:     fmt.Sprintf("%s-%s", version, release),
644			Arch:        "src",
645			BinaryNames: []string{binaryName},
646		}
647	}
648	
649	// https://github.com/aquasecurity/trivy/blob/51f2123c5ccc4f7a37d1068830b6670b4ccf9ac8/pkg/fanal/analyzer/pkg/rpm/rpm.go#L212-L241
650	func splitFileName(filename string) (name, ver, rel string, err error) {
651		const expected = "<name>-<version>-<release>.<arch>.rpm"
652		unexpected := func() (string, string, string, error) {
653			return "", "", "", xerrors.Errorf("unexpected file name. expected: %q, actual: %q", expected, filename)
654		}
655		if !strings.HasSuffix(filename, ".rpm") {
656			return unexpected()
657		}
658		stem := strings.TrimSuffix(filename, ".rpm")
659	
660		archIndex := strings.LastIndex(stem, ".")
661		if archIndex <= 0 || archIndex == len(stem)-1 {
662			return unexpected()
663		}
664	
665		relIndex := strings.LastIndex(stem[:archIndex], "-")
666		if relIndex <= 0 || relIndex == archIndex-1 {
667			return unexpected()
668		}
669		rel = stem[relIndex+1 : archIndex]
670	
671		verIndex := strings.LastIndex(stem[:relIndex], "-")
672		if verIndex <= 0 || verIndex == relIndex-1 {
673			return unexpected()
674		}
675		ver = stem[verIndex+1 : relIndex]
676		name = stem[:verIndex]
677	
678		if epoch, packageName, ok := strings.Cut(name, ":"); ok {
679			if epoch == "" || packageName == "" {
680				return unexpected()
681			}
682			for _, digit := range epoch {
683				if digit < '0' || digit > '9' {
684					return unexpected()
685				}
686			}
687			name = packageName
688			ver = epoch + ":" + ver
689		}
690		return name, ver, rel, nil
691	}
