693	func (o *redhatBase) parseRpmQfLine(line string) (pkg *models.Package, ignored bool, err error) {
694		for _, suffix := range []string{
695			"Permission denied",
696			"is not owned by any package",
697			"No such file or directory",
698		} {
699			if strings.HasSuffix(line, suffix) {
700				return nil, true, nil
701			}
702		}
703		pkg, _, err = o.parseInstalledPackagesLine(line)
704		return pkg, false, err
705	}
